 *  figure: then it is the sum of the figures there are. With `cap`, it is at most the cap (an n/a one
 *  is not capped). */
export function personDueCents(claims: Claim[], floor: string, pct: string | undefined, pctOn?: (date: string) => string | undefined, late?: Late, cap?: string | null): bigint | null {
  let sum = 0n;
  let any = false;
  for (const c of counted(claims)) {
    const due = claimDueCents(c, floor, pctOn ? pctOn(c.date) : pct, late);
    if (due === null) continue;
    sum += due;
    any = true;
  }
  if (pct === undefined && !any) return null;
  return capCents(sum, cap);
}

/** A due-total at most the sheet's `cap` (null or blank: no cap); n/a is not capped. */
export function capCents(due: bigint | null, cap?: string | null): bigint | null {
  if (due === null || cap == null || cap === '') return due;
  const most = hundredths(cap);
  return due > most ? most : due;
}

/** How much a due-total is over the sheet's `cap`: 0 when it is not (or is n/a, or there is no cap). */
export function excessCents(due: bigint | null, cap?: string | null): bigint {
  const capped = capCents(due, cap);
  return due === null || capped === null ? 0n : due - capped;
}

/** Whether a claim is overdue: it is OPEN (or PENDING) and its due-by is before the sheet's `today`. */
export function overdue(claim: Claim, today: string): boolean {
  return isOpen(claim) && today !== '' && claim.dueBy < today;
}

/** These claims' overdue ones: their count, and their dues with late charges added up in cents (n/a ones skipped).
 *  `pctOn` is the rate in force on a claim's date. */
export function overdueFigures(claims: Claim[], late: Late, floor: string, pctOn: (date: string) => string | undefined): { count: number; cents: bigint } {
  const over = claims.filter((c) => overdue(c, late.today));
  const cents = over.reduce<bigint>((sum, c) => sum + (claimDueCents(c, floor, pctOn(c.date), late) ?? 0n), 0n);
  return { count: over.length, cents };
}
import { gradeOn, heldOnBy, usePeople } from '../people/usePeople';
import { rateOn, totalDue, useRates } from '../rates/useRates';
import { useCap, useFloor, useLate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheet';
import { claimed, live, overdueFigures, personDueCents, useClaims } from './useClaims';

/**
 * The sheet's totals: its claimed-total, everyone's counted (OPEN or SETTLED) claims added up
 * (not OPEN ones dated within their person's hold, unless stated), and its due-total, everyone's due-total
 * added up (a person whose due-total is n/a is skipped), and how many of the claims that count are
 * overdue, with their dues added up. One place, so every screen repeating a total shows the same figure.
 */
export function useSheetTotals(sheet: string) {
  const { data: all = [] } = useClaims(sheet);
  const { data: people = [] } = usePeople(sheet);
  const claims = live(all, heldOnBy(people));
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const cap = useCap(sheet);
  const dues = people.map((p) =>
    personDueCents(claims.filter((c) => c.personId === p.id), floor, rateOn(rates, gradeOn(p, today), today), (d) => rateOn(rates, gradeOn(p, d), d), late, cap),
  );
  const over = people.map((p) =>
    overdueFigures(claims.filter((c) => c.personId === p.id), late, floor, (d) => rateOn(rates, gradeOn(p, d), d)),
  );
  return {
    claimedTotal: claimed(claims),
    dueTotal: totalDue(dues),
    overdueCount: over.reduce((n, o) => n + o.count, 0),
    overdueTotal: totalDue(over.map((o) => o.cents)),
  };
}
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { STATUSES, live, personDueCents, useClaims } from '../claims/useClaims';
import { GRADES, gradeOn, heldOn, usePeople } from '../people/usePeople';
import { periodDue, usePeriods } from '../periods/usePeriods';
import { rateOn, totalDue, useRates } from '../rates/useRates';
import { useCap, useFloor, useLate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheet';

/**
 * The sheet in figures, each worked out as the list works it out. Per grade: how many people not
 * retired are on it on the sheet's today, and their due-totals added up (n/a ones skipped). Per
 * period: its due-total. Per status: how many of the sheet's claims have it.
 */
function SummaryPanel({ sheet }: { user: string; sheet: string }) {
  const { data: all = [] } = useClaims(sheet);
  const { data: everyone = [] } = usePeople(sheet);
  const { data: periods = [] } = usePeriods(sheet);
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const cap = useCap(sheet);
  const people = everyone.filter((p) => !p.retired);
  const dueOf = (p: (typeof people)[number]) =>
    personDueCents(
      live(all.filter((c) => c.personId === p.id), (_, date) => heldOn(p, date)),
      floor,
      rateOn(rates, gradeOn(p, today), today),
      (d) => rateOn(rates, gradeOn(p, d), d),
      late,
      cap,
    );

  return (
    <section data-testid="summary-panel">
      <h2>Summary</h2>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const on = people.filter((p) => gradeOn(p, today) === g);
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{on.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>{totalDue(on.map(dueOf))}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due</th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>{periodDue(p, all, everyone, rates, floor, late)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{all.filter((c) => c.status === s).length}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

